fixtures.case-b/src/auth.mjs:
export function createAuth() {
  let nextToken = 0;
  const credentials = new Map([['alice', 'initial-password']]);
  const sessions = new Map();
  return {
    login(name, password) {
      if (credentials.get(name) !== password) return { status: 401 };
      const token = `session-${++nextToken}`;
      sessions.set(token, name);
      return { status: 200, token };
    },
    profile(token) {
      return sessions.has(token) ? { status: 200, name: sessions.get(token) } : { status: 401 };
    }
  };
}

