import { test } from 'node:test';
import assert from 'node:assert/strict';
import { createMembers } from '../src/members.mjs';
for (const email of ['alex@example.test', 'ALEX@EXAMPLE.TEST']) {
  test(`reject duplicate ${email}`, () => {
    const members = createMembers();
    members.create('alex@example.test');

    const result = members.create(email);

    assert.equal(result.status, 409);
    assert.equal(members.list().length, 1);
  });
}
test('create member', () => {
  const members = createMembers();

  const result = members.create('new@example.test');

  assert.deepEqual(result, { status: 201, email: 'new@example.test' });
  assert.deepEqual(members.list(), [{ email: 'new@example.test' }]);
});

fixtures.case-a/src/members.mjs:
export function createMembers() {
  const records = new Map();
  return {
    create(email) {
      const canonical = email.toLowerCase();
      if (!canonical || !canonical.includes('@')) return { status: 400 };
      if (records.has(canonical)) return { status: 409 };
      records.set(canonical, { email: canonical });
      return { status: 201, email: canonical };
    },
    list() { return [...records.values()]; }
  };
}
